mapper.select:
select i.* from cost_review_issue i
where i.del_flag = '0' and i.review_task_id = #{reviewTaskId}
and i.issue_type = #{issueType}
and i.issue_level = #{issueLevel}
and i.status = #{status}

    and (i.item_code_snapshot like concat('%', #{keyword}, '%')
         or i.item_name_snapshot like concat('%', #{keyword}, '%')
         or i.issue_title like concat('%', #{keyword}, '%'))

order by field(i.issue_level, 'CRITICAL','HIGH','MEDIUM','LOW','INFO'), i.id asc
